public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n < 2) {
        return false;
    }

    int sum = 0;
    for (int num : nums) {
        sum += num;
    }

    // The average of the whole array is sum / n.
    // If we split into two parts of size k and n-k, both must have the same average.
    // So sum / n = (sum of part1) / k = (sum of part2) / (n-k)
    // This implies sum * k must be divisible by n, and the target sum for part1 is sum * k / n.

    // We can use a DP approach: dp[k][s] = true if we can pick k elements with sum s.
    // But s can be large. Let's find the min and max values to bound s.

    int minVal = Integer.MAX_VALUE;
    int maxVal = Integer.MIN_VALUE;
    for (int num : nums) {
        minVal = Math.min(minVal, num);
        maxVal = Math.max(maxVal, num);
    }

    // We only need to check k from 1 to n/2 (since if a subset of size k works, the complement of size n-k also works)
    // Actually, we can check k from 1 to n-1, but by symmetry, checking up to n/2 is sufficient.

    // Let's use a set-based DP to track possible sums for each count.
    // dp[k] is a set of possible sums using k elements.

    // To optimize, we can use a boolean array for sums, but the range might be large.
    // Let's use a set of integers for each k.

    // Actually, a more efficient approach: use a 2D boolean array where dp[k][s] indicates
    // whether it's possible to select k elements with sum s.
    // The range of s: min possible sum for k elements is k * minVal, max is k * maxVal.

    // Let's use a set-based approach to avoid large arrays.

    // dp[k] = set of possible sums
    java.util.Set<Integer>[] dp = new java.util.Set[n + 1];
    for (int i = 0; i <= n; i++) {
        dp[i] = new java.util.HashSet<>();
    }
    dp[0].add(0);

    for (int num : nums) {
        // Iterate backwards to avoid using the same element multiple times
        for (int k = n - 1; k >= 1; k--) {
            for (int s : dp[k - 1]) {
                dp[k].add(s + num);
            }
        }
    }

    // Now check for each k from 1 to n/2 (inclusive)
    for (int k = 1; k <= n / 2; k++) {
        if (sum * k % n != 0) {
            continue;
        }
        int targetSum = sum * k / n;
        if (dp[k].contains(targetSum)) {
            return true;
        }
    }

    return false;
}

