public String makeGood(String s) {
    if (s == null || s.isEmpty()) {
        return s;
    }

    StringBuilder sb = new StringBuilder();
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (sb.length() > 0) {
            char prev = sb.charAt(sb.length() - 1);
            if (Math.abs(c - prev) == 32) {
                sb.deleteCharAt(sb.length() - 1);
                continue;
            }
        }
        sb.append(c);
    }

    return sb.toString();
}

