public int minOperations(String[] logs) {
    if (logs == null || logs.length == 0) {
        return 0;
    }
    int depth = 0;
    for (String log : logs) {
        if (log == null) {
            continue;
        }
        if (log.equals("../")) {
            if (depth > 0) {
                depth--;
            }
        } else if (log.equals("./")) {
            // stay in the same folder, do nothing
        } else {
            // entering a subfolder
            depth++;
        }
    }
    return depth;
}

