public static List<Integer> findSteppingNumbers(int low, int high) {
    List<Integer> result = new ArrayList<>();
    if (low > high) {
        return result;
    }

    // Handle single digit numbers (0-9)
    for (int i = Math.max(0, low); i <= Math.min(9, high); i++) {
        result.add(i);
    }

    // Use BFS to generate stepping numbers with more than one digit
    Queue<Integer> queue = new LinkedList<>();
    for (int i = 1; i <= 9; i++) {
        queue.offer(i);
    }

    while (!queue.isEmpty()) {
        int current = queue.poll();
        if (current > high) {
            continue;
        }
        if (current >= low && current > 9) {
            result.add(current);
        }

        int lastDigit = current % 10;
        int next1 = current * 10 + (lastDigit - 1);
        int next2 = current * 10 + (lastDigit + 1);

        if (lastDigit > 0 && next1 <= high) {
            queue.offer(next1);
        }
        if (lastDigit < 9 && next2 <= high) {
            queue.offer(next2);
        }
    }

    Collections.sort(result);
    return result;
}

