public static int squarePermutations(int[] A) {
    if (A == null || A.length == 0) {
        return 0;
    }

    int n = A.length;
    if (n == 1) {
        return 1;
    }

    // Count frequencies
    int maxVal = 0;
    for (int v : A) {
        if (v > maxVal) maxVal = v;
    }

    int[] freq = new int[maxVal + 1];
    for (int v : A) {
        freq[v]++;
    }

    // Precompute which pairs sum to a perfect square
    // Max possible sum is 2 * maxVal
    int maxSum = 2 * maxVal;
    boolean[] isSquare = new boolean[maxSum + 1];
    for (int i = 0; i * i <= maxSum; i++) {
        isSquare[i * i] = true;
    }

    // Memoization: key is (index, remaining counts encoded)
    // Since values can be up to some limit, we use a map with a string key or a custom key
    // For efficiency, we'll use a HashMap with a key that represents the state
    // State: current position and the remaining frequency array
    // We'll encode the frequency array as a string key

    java.util.Map<String, Integer> memo = new java.util.HashMap<>();

    // Start with the full frequency array
    int[] initialFreq = freq.clone();
    String initialKey = encodeState(initialFreq);

    return dfs(0, initialFreq, isSquare, memo, initialKey);
}

