public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0) {
        return new int[0];
    }

    int rows = mat.length;
    int cols = mat[0].length;
    int total = rows * cols;
    int[] result = new int[total];

    int idx = 0;
    // There are rows + cols - 1 diagonals
    for (int d = 0; d < rows + cols - 1; d++) {
        if (d % 2 == 0) {
            // Even diagonal: go from bottom-left to top-right
            // Start row: max(0, d - cols + 1)
            // Start col: min(d, cols - 1)
            int startRow = Math.max(0, d - cols + 1);
            int startCol = Math.min(d, cols - 1);
            int r = startRow;
            int c = startCol;
            while (r >= 0 && c < cols) {
                result[idx++] = mat[r][c];
                r--;
                c++;
            }
        } else {
            // Odd diagonal: go from top-right to bottom-left
            // Start row: min(d, rows - 1)
            // Start col: max(0, d - rows + 1)
            int startRow = Math.min(d, rows - 1);
            int startCol = Math.max(0, d - rows + 1);
            int r = startRow;
            int c = startCol;
            while (r < rows && c >= 0) {
                result[idx++] = mat[r][c];
                r++;
                c--;
            }
        }
    }

    return result;
}

