public static List<String> centerSymmetricNumbers(int n) {
    List<String> result = new ArrayList<>();
    if (n <= 0) {
        return result;
    }

    // Mapping of digits to their center-symmetric counterparts
    Map<Character, Character> symmetricMap = new HashMap<>();
    symmetricMap.put('0', '0');
    symmetricMap.put('1', '1');
    symmetricMap.put('6', '9');
    symmetricMap.put('8', '8');
    symmetricMap.put('9', '6');

    // For building the first half
    char[] firstHalfDigits = {'0', '1', '6', '8', '9'};

    int halfLen = n / 2;

    // Generate all possible first halves
    List<String> firstHalves = new ArrayList<>();
    generateFirstHalves(firstHalfDigits, halfLen, new StringBuilder(), firstHalves);

    for (String firstHalf : firstHalves) {
        // Build the second half by reversing the first half and mapping each digit
        StringBuilder secondHalf = new StringBuilder();
        for (int i = firstHalf.length() - 1; i >= 0; i--) {
            char c = firstHalf.charAt(i);
            secondHalf.append(symmetricMap.get(c));
        }

        String secondHalfStr = secondHalf.toString();

        if (n % 2 == 0) {
            // Even length: just concatenate first half and second half
            String num = firstHalf + secondHalfStr;
            // For even length, leading zeros are allowed (e.g., "00" is valid)
            result.add(num);
        } else {
            // Odd length: need a middle digit that is symmetric to itself
            // Middle digits can be '0', '1', '8'
            char[] middleDigits = {'0', '1', '8'};
            for (char mid : middleDigits) {
                String num = firstHalf + mid + secondHalfStr;
                // For odd length, leading zeros are not allowed (except for n=1)
                if (n == 1 || num.charAt(0) != '0') {
                    result.add(num);
                }
            }
        }
    }

    return result;
}

