public static int calculateUniqueSum(int[] nums) {
    if (nums == null) {
        return 0;
    }
    java.util.Set<Integer> uniqueSet = new java.util.HashSet<>();
    java.util.Set<Integer> duplicateSet = new java.util.HashSet<>();
    for (int num : nums) {
        if (duplicateSet.contains(num)) {
            continue;
        }
        if (uniqueSet.contains(num)) {
            uniqueSet.remove(num);
            duplicateSet.add(num);
        } else {
            uniqueSet.add(num);
        }
    }
    int sum = 0;
    for (int num : uniqueSet) {
        sum += num;
    }
    return sum;
}

