public static int minPerfectSquareSum(int n) {
    if (n <= 0) {
        return 0;
    }

    // Check if n is a perfect square
    int sqrt = (int) Math.sqrt(n);
    if (sqrt * sqrt == n) {
        return 1;
    }

    // Check if n can be represented as sum of 2 perfect squares
    for (int i = 1; i <= sqrt; i++) {
        int remaining = n - i * i;
        int j = (int) Math.sqrt(remaining);
        if (j * j == remaining) {
            return 2;
        }
    }

    // Check if n can be represented as sum of 3 perfect squares
    // According to Legendre's three-square theorem, a number can be represented as sum of three squares
    // if and only if it is not of the form 4^a * (8b + 7)
    int temp = n;
    while (temp % 4 == 0) {
        temp /= 4;
    }
    if (temp % 8 != 7) {
        return 3;
    }

    // Otherwise, it must be 4
    return 4;
}

